    ["<Chat_Telegram>赞美愚者！</>{{player.name}}<Chat_Telegram>被命运眷顾，自灵界召唤获得了</>{{item.name}}<Chat_Telegram>，令风尚之光重现世间！</>"] = "<Chat_Telegram>Слава Шуту!</>{{player.name}}<Chat_Telegram> был(а) благословлён(а) судьбой и с помощью Призыва Мира Духов получил(а)</>{{item.name}}<Chat_Telegram>, вернув свет моды в этот мир!</>",
    ["<Color_Apprentice>近战刺客</>"] = "<Color_Apprentice>Убийца ближнего боя</>",
    ["<Color_Bard>近战输出</>"] = "<Color_Bard>Ближний бой (урон)</>",
