    ["{\n                        \"否\": False,\n                        \"是\": True,\n                    }"] = "{\n «Нет»: ложь,\n «Да»: правда,\n }",
    ["{\n                        \"轻攻击\": \"LightHit\",\n                        \"默认击退\": \"HitBack\",\n                        \"击退100cm_控制0.3秒\": \"HitBack_100_9F\",\n                        \"击退200cm_控制0.3秒\": \"HitBack_200_9F\",\n                        \"击退300cm_控制0.3秒\": \"HitBack_300_9F\",\n                        \"击倒\": \"HitDown\",\n                        \"击飞\": \"HitFly\",\n                        \"挑空\": \"HitFloat\",\n                        \"拖拽\": \"HitDrag\",\n                        \"僵直攻击\": \"HitStiff\"\n                    }"] = "{\n \"Легкая атака\": \"LightHit\",\n \"Отбрасывание по умолчанию\": \"HitBack\",\n \"Отбрасывание 100cm_Control 0,3 секунды\": \"HitBack_100_9F\",\n \"Отбрасывание 200cm_Control 0,3 секунды\": \"HitBack_200_9F\",\n \"Отбрасывание 300cm_Control 0,3 секунды\": \"HitBack_300_9F\",\n \"Нокдаун\": \"HitDown\",\n \"HitFly\": \"HitFly\",\n \"HitFloat\": \"HitFloat\",\n \"Drag\": \"HitDrag\",\n \"Жесткая атака\": \"HitStiff\"\n }",
    ["{\n    \"轻攻击\": \"LightHit\",\n    \"击退\": \"HitBack\",\n    \"击倒\": \"HitDown\",\n    \"击飞\": \"HitFly\",\n    \"挑空\": \"HitFloat\",\n    \"拖拽\": \"HitDrag\",\n    \"僵直攻击\": \"HitStiff\",\n    \"拳击玩法轻受击\": \"BoxHitLight\",\n    \"拳击玩法重受击\": \"BoxHitHeavy\"\n}"] = "{\n «Легкая атака»: «LightHit»,\n «Отбрасывание»: «HitBack»,\n «Нокдаун»: «HitDown»,\n «Полет»: «HitFly»,\n «Плавание»: «HitFloat»,\n «Перетаскивание»: «HitDrag»,\n «Жесткая атака»: \"HitStiff\",\n \"BoxHitLight\",\n \"BoxHitLight\",\n \"BoxHitHeavy\": \"BoxHitHeavy\"\n}",
    ["{\n  \"代表朝向跟着持有者旋转\": \"FALSE\",\n  \"代表朝向在世界坐标系里保持不变\": \"TRUE\"\n}"] = "{\n \"Означает, что ориентация вращается вместе с держателем\": \"FALSE\",\n \"Означает, что ориентация остается неизменной в мировой системе координат\": \"TRUE\"\n}",
    ["{\n  \"竞速玩法\": \"0\"}"] = "{\n «Гоночный геймплей»: «0»}",
    ["{\n\"Bool\": \"0\",\n\"Int\": \"1\",\n\"Str\": \"2\",\n\"nil\": \"3\"\n}\n表达ParamValues上对应参数位的参数类型"] = "{\n\"Bool\": \"0\",\n\"Int\": \"1\",\n\"Str\": \"2\",\n\"nil\": \"3\"\n}\n выражает тип параметра соответствующего бита параметра в ParamValues",
    ["{\n\"Puddle这里是类似廷根的水坑材质, 不是真正的水面\":\"0\",\n\"Grass草地\":\"1\",\n\"Stone石头\":\"2\",\n\"Dirt土地\":\"3\",\n\"Wood木板\":\"4\",\n\"Blanket地毯\":\"5\",\n\"Fabric布棚\":\"6\",\n\"Glass玻璃\":\"7\",\n\"Ice冰面\":\"8\",\n\"Marsh湿地\":\"9\",\n\"Metal实心金属\":\"10\",\n\"Sand沙地\":\"11\",\n\"Snow雪地\":\"12\",\n\"Steelplate钢板\":\"13\",\n\"Tile水坑\":\"14\",\n\"Water水面\":\"15\",\n\"WoodBoard木板\":\"16\"\n}"] = "{\n\"Puddle (материал лужи, как в Тингене, не настоящая вода)\":\"0\",\n\"Grass (трава)\":\"1\",\n\"Stone (камень)\":\"2\",\n\"Dirt (земля)\":\"3\",\n\"Wood (доски)\":\"4\",\n\"Blanket (ковер)\":\"5\",\n\"Fabric (тканевый навес)\":\"6\",\n\"Glass (стекло)\":\"7\",\n\"Ice (лед)\":\"8\",\n\"Marsh (болото)\":\"9\",\n\"Metal (цельный металл)\":\"10\",\n\"Sand (песок)\":\"11\",\n\"Snow (снег)\":\"12\",\n\"Steelplate (стальная плита)\":\"13\",\n\"Tile (плитка)\":\"14\",\n\"Water (водная гладь)\":\"15\",\n\"WoodBoard (деревянный настил)\":\"16\"\n}",
    ["{\n\"RUN\": \"0\",\n\"WALK\": \"1\",\n\"SPRINT(疾跑)\": \"2\"\n}"] = "{\n\"БЕГ\": \"0\",\n\"ХОДЬБА\": \"1\",\n\"СПРИНТ\": \"2\"\n}",
    ["{\n\"三段跳落地\": 0,\n\"x 键落地\": 1\n}"] = "{\n\"Приземление в тройном прыжке\": 0,\n\"x ключевое приземление\": 1\n}",
    ["{\n\"上层传入LockTarget\": \"0\",\n\"持有者\": \"1\",\n\"始作俑者\": \"2\",\n\"一仇目标\": \"3\"\n}"] = "{\n\"Переданный верхним слоем LockTarget\": \"0\",\n\"Владелец\": \"1\",\n\"Зачинщик\": \"2\",\n\"Главная цель угрозы\": \"3\"\n}",
    ["{\n\"不指定\":\"\",\n\"全体敌方玩家\": \"Enemy(Player)\",\n\"全体敌方玩家（包含尸体）\": \"Enemy(Player)(IncludeDead)\"\n}"] = "{\n\"Не указано\":\"\",\n\"Все вражеские игроки\": \"Enemy(Player)\",\n\"Все вражеские игроки (включая трупы)\": \"Enemy(Player)(IncludeDead)\"\n}",
    ["{\n\"不指定\":\"\",\n\"命中目标数（技能和法术场中的范围命中后使用该参数）\":\"hitnum\",\n\"筛选目标数（使用目标筛选时使用该参数）\": \"tarnum\",\n\"职业资源改变值（包括向上溢出值）\": \"propdiff\",\n\"职业资源改变值（实际改变值）\": \"proprealdiff\",\n\"最近一次驱散的buff层数\": \n\"buffnum\"\n}"] = "{\n\"Не указано\":\"\",\n\"Число пораженных целей (параметр для попадания по области в навыках и полях заклинаний)\":\"hitnum\",\n\"Число отобранных целей (параметр при отборе целей)\": \"tarnum\",\n\"Изменение ресурса профессии (включая переполнение)\": \"propdiff\",\n\"Изменение ресурса профессии (фактическое)\": \"proprealdiff\",\n\"Число слоёв последнего рассеянного баффа\": \n\"buffnum\"\n}",
    ["{\n\"不指定类型\": \"\",\n\"中性Buff\": \"0\",\n\"增益Buff\": \"1\",\n\"减益Buff\": \"2\"\n}"] = "{\n\"Неопределенный тип\": \"\",\n\"Нейтральное усиление\": \"0\",\n\"Усиление усиления\": \"1\",\n\"Усиление дебаффа\": \"2\"\n}",
    ["{\n\"从胶囊体中心开始算距离\": \"False\",\n\"从胶囊体边缘开始算距离\": \"True\"\n}"] = "{\n\"Рассчитать расстояние от центра капсулы\": \"Ложь\",\n\"Рассчитать расстояние от края капсулы\": \"Истина\"\n}",
    ["{\n\"全体(默认值)\":\"All\",\n\"敌方\": \"Enemy\",\n\"友方（不包含自己）\": \"Friend\",\n\"友方\": \"FriendAndSelf\",\n}"] = "{\n\"Все (по умолчанию)\":\"All\",\n\"Враги\": \"Enemy\",\n\"Союзники (кроме себя)\": \"Friend\",\n\"Союзники\": \"FriendAndSelf\",\n}",
    ["{\n\"全体玩家\": \"0\",\n\"技能/buff持有者\": \"1\",\n\"锁定目标\": \"2\"\n}"] = "{\n\"Все игроки\": \"0\",\n\"Обладатели навыков/баффов\": \"1\",\n\"Зафиксировать цель\": \"2\"\n}",
    ["{\n\"变多or变少\": \"both\",\n\"变少\": \"down\",\n\"变多\": \"up\"\n}"] = "{\n\"получить больше или меньше\": \"оба\",\n\"получить меньше\": \"вниз\",\n\"получить больше\": \"вверх\"\n}",
    ["{\n\"大风车（摇杆方向，全身动画）\": \"0\",\n\"滚轮子（面向方向，全身动画）\": \"1\",\n\"滑板鞋（摇杆方向，半身动画）\": \"2\",\n\"踱步挠头（面向方向，全身动画）\": \"3\"\n}"] = "{\n\"Большая ветряная мельница (направление джойстика, анимация всего тела)\": \"0\",\n\"Вращающееся колесо (направление лицом, анимация всего тела)\": \"1\",\n\"Обувь для скейтборда (направление джойстика, анимация половины тела)\": \"2\",\n\"Ходите и почесывайте голову (направление лицом, анимация всего тела)\": \"3\"\n}",
    ["{\n\"怪物\": \"1\",\n\"NPC\": \"2\",\n\"场景物件\": \"3\"\n}"] = "{\n\"Монстр\": \"1\",\n\"NPC\": \"2\",\n\"Объект сцены\": \"3\"\n}",
    ["{\n\"技能/buff对象目标(持有者/始作俑者)\": \"0\",\n\"关卡/场景为目标\": \"1\",\n\"范围内对象为目标\": \"2\",\n\"目标筛选为目标\": \"3\",\n\"黑板 tarlist\":\"4\"\n}"] = "{\n\"Цель навыка/баффа (владелец/инициатор)\": \"0\",\n\"Уровень/сцена является целью\": \"1\",\n\"Объект в пределах диапазона является целью\": \"2\",\n\"Целевой фильтр является целью\": \"3\",\n\"Список досок\":\"4\"\n}",
    ["{\n\"按下或抬起\": \"both\",\n\"按下\": \"down\",\n\"抬起\": \"up\"\n}"] = "{\n\"нажмите или поднимите\": \"оба\",\n\"нажмите\": \"вниз\",\n\"поднимите\": \"вверх\"\n}",
