    ["{\n\"无\": \"\",\n\"击退\": \"HitBack\",\n\"击倒\": \"HitDown\",\n\"击飞\": \"HitFly\",\n\"挑空\": \"HitFloat\",\n\"拖拽\": \"HitDrag\",\n\"僵直\": \"HitStiff\"\n}"] = "{\n\"Нет\": \"\",\n\"Перетаскивание\": \"HitDrag\",\n\"Stiff\": \"HitStiff\"\n}",
