    ["{\n\"无限制\": \"0\",\n\"限制技能复活\": \"1\",\n\"限制自身功能复活\": \"2\",\n\"禁止复活\": \"3\"\n}"] = "{\n\"Без ограничений\": \"0\",\n\"Ограничить воскрешение умениями\": \"1\",\n\"Ограничить собственное воскрешение\": \"2\",\n\"Воскрешение запрещено\": \"3\"\n}",
    ["{\n\"根据道具表\": \"1\",\n\"绑定\": \"2\",\n\"非绑定\": \"3\"\n}"] = "{\n\"Согласно таблице реквизитов\": \"1\",\n\"Привязано\": \"2\",\n\"Непривязано\": \"3\"\n}",
