    ["你获得了<Chat_Highlight>%d</>征服声望。"] = "Вы получили <Chat_Highlight>%d</> Престижа завоевания.",
    ["你获得了<Chat_Highlight>%d</>战功。"] = "Вы получили <Chat_Highlight>%d</> Боевых заслуг.",
    ["你获得了“水手”途径的部分恩赐，冲刺不再有冷却限制"] = "Вы получили некоторые благословения пути «Моряка»; спринт больше не имеет ограничения по перезарядке.",
    ["你获得了“水手”途径的部分恩赐，冲刺不再有冷却限制。"] = "Вы получили часть дара «Пути моряка», спринт больше не имеет ограничения по времени восстановления.",
    ["你获得了“观众”途径的部分心理暗示：你受到的治疗量增加40%，但你潜意识中不愿伤害他人，造成的治疗和伤害下降20%。"] = "Вы получили некоторые психологические рекомендации по пути «Наблюдатель»: получаемое вами исцеление увеличивается на 40%, но подсознательно вы не желаете причинять вред другим, что снижает исцеление и наносимый вами урон на 20%.",
    ["你获得了“观众”途径的部分心理暗示：你造成和受到的治疗量增加30%，但你潜意识中不愿伤害他人，暴击下降10%。"] = "Вы получили часть Психологического предложения Пути наблюдателя: исцеление, которое вы наносите и получаете, увеличивается на 30%, но подсознательно вы не желаете причинять вред другим, критический удар уменьшен на 10%.",
    ["你获得了仲裁人序列的能力，攻击时会产生一个领域，领域内己方暴击和伤害加深提高，敌方防御和格挡降低。"] = "Вы получили способность Последовательности Арбитра: атака создаёт поле, внутри которого у союзников повышаются шанс крита и усиление урона, а у врагов снижаются защита и блокирование.",
    ["你获得了仲裁人序列的能力，攻击时会产生一个领域，领域内己方暴击和伤害增幅提升，敌方防御力和格挡降低。"] = "Вы получили способности Последовательности Арбитра. Атака создает область, в которой вероятность критического удара и урон вашей стороны увеличиваются, а защита и блок противника уменьшаются.",
    ["你获得了巨人的形体，你的体型增大 100%，并且在战斗中会自动击退所有靠近你 1米以内的敌人。"] = "Вы получили форму Великана; ваш размер увеличивается на 100%, и во время боя вы автоматически отбрасываете всех врагов в радиусе 1 метра от вас.",
    ["你获得了巨人的形体，你的体型增大 100%，并且在战斗中每8秒击退所有靠近你 2米以内的敌人。"] = "Вы приобрели телосложение Гиганта; ваш размер увеличивается на 100%, и вы отбрасываете всех врагов в радиусе 2 метров от вас каждые 8 ​​секунд в бою.",
    ["你获得了灵界的援助，你攻击时，通灵巨兽有10%概率协助你进行攻击，此效果每5秒最多触发一次。"] = "Вы получили помощь Мира Духов. Когда вы атакуете, зверь-медиум с вероятностью 10% поможет вам в атаке. Этот эффект может срабатывать не чаще одного раза в 5 секунд.",
    ["你获得了灵界的援助，你攻击时，通灵巨兽有概率协助你进行攻击。"] = "Вы заручились поддержкой духовного мира: при вашей атаке медиумический исполин может нанести совместный удар.",
    ["你获得了破晓勋章"] = "Вы получили Медаль Рассвета.",
    ["你获得了穿行空间的能力，战斗中每15秒，你会转移到另一个位面，受到的伤害大幅减少 ，持续 3 秒。"] = "Вы получили возможность путешествовать в космосе. Каждые 15 секунд в бою вы будете переходить в другую плоскость, и получаемый урон будет значительно снижен на 3 секунды.",
    ["你获得了门序列穿行空间的能力，战斗中，每隔一段时间，你会随机转移到另一个位面，受到的伤害减少 99%，持续 3 秒。"] = "Вы получаете возможность путешествовать в космосе, пройдя через врата. Во время боя вы время от времени будете случайным образом переноситься в другой самолет, а получаемый вами урон будет снижен на 99% на 3 секунды.",
    ["你被%s邀请加入了%s群组。"] = "%s пригласил вас присоединиться к группе %s.",
    ["你被2-049盯上了，快远离队友！"] = "На вас нацелен 2-049, держитесь подальше от товарищей по команде!",
    ["你被净化了，进入虚弱状态，攻击力降低*f**"] = "Вы очистились, вошли в состояние слабости и уменьшили атаку на *f**.",
    ["你被封印物2-049盯上了，<Dungeon_Highlight>呼叫队友点击按钮</>解救"] = "На вас нацелен Запечатанный Артефакт 2-049, <Dungeon_Highlight> позвоните своим товарищам по команде и нажмите кнопку </>, чтобы спасти",
    ["你被封印物2-049盯上了，<Dungeon_Highlight>尽快远离队友！</>"] = "Вы стали целью запечатанного артефакта 2-049, <Dungeon_Highlight> держитесь подальше от своих товарищей по команде как можно скорее! </>",
    ["你被母亲眷顾了！"] = "Вы получили благосклонность Матери!",
    ["你被洪流淹没了……"] = "Ты утонул в потоке...",
    ["你被荆丛扎得满手是血。找一把【合适】的武器斩断它们吧。（提示：查看荆丛旁石柱上的刻字。）"] = "Твои руки изранены терновником в кровь. Найди [подходящее] оружие, чтобы срубить его. (Подсказка: осмотри надпись на каменной колонне рядом с терновником.)",
    ["你要是不小心滑倒了，明天的头条就会是——"] = "Если ты поскользнешься и упадешь, завтрашний заголовок будет таким:",
    ["你要晕船药吗？我这里有特效药。"] = "Хотите лекарство от морской болезни? У меня есть специальное средство.",
    ["你要爆炸了！快去请小矮人将你带到空中！"] = "Ты сейчас взорвёшься! Скорее попроси Гнома поднять тебя в воздух!",
    ["你要的货"] = "Товары, которые вы хотели",
    ["你要等一等 再等一等"] = "Тебе нужно подождать ещё немного, совсем чуть-чуть.",
    ["你触碰了“窥秘人”的禁忌知识：造成的伤害增加30%，但你的身体变得如玻璃般脆弱，最大生命值降低15%。"] = "Вы прикоснулись к запретному знанию «Таинственного жреца»: наносимый урон увеличивается на 30%, но ваше тело становится хрупким, как стекло, а максимальное здоровье снижается на 15%.",
    ["你触碰了“隐秘学派”的禁忌知识：造成的伤害增加40%，但你的身体变得如玻璃般脆弱，最大生命值降低15%。"] = "Вы прикоснулись к Запретным знаниям Ордена Отшельников: наносимый урон увеличился на 40%, но ваше тело стало хрупким, как стекло, максимальное здоровье уменьшилось на 15%.",
    ["你认识我师父？"] = "Ты знаешь моего хозяина?",
    ["你记住 你惹到猎龙帮了！"] = "Помните, вы связались с бандой охотников на драконов!",
    ["你记得吗？我们就是跪在这里，看着玛莎倒下，托马斯被杀死，安妮消失……"] = "Помнишь? Мы стояли на коленях прямо здесь и смотрели, как падает Марта, как убивают Томаса, как исчезает Энни...",
    ["你诱惑的仆从已达上限，上限是%i个"] = "Вы достигли предела соблазненных слуг; предел — %i.",
    ["你说什么？"] = "Что вы сказали?",
    ["你说得对"] = "Ты прав",
    ["你说得没错，至少他对女神的呼唤是从一而终的。"] = "Вы правы, по крайней мере, его призыв к Богине последователен.",
    ["你说我来哈德罗百货做侍者怎么样？"] = "Что вы думаете о том, что я работаю официантом в универмаге «Гарольд»?",
    ["你说我要不要邀请她去猎狐？但她似乎更喜欢安静……"] = "Как думаешь, мне стоит пригласить ее поохотиться на лис? Но она, кажется, предпочитает тишину...",
    ["你说的山……"] = "Гора, которую вы упомянули...",
    ["你踏入了非凡之路，获得最初的特性，力量虽微，却已超越常人。"] = "Вы вступили на путь необыкновенного и обрели свои первоначальные характеристики; хотя твоя сила и невелика, ты уже превзошёл обычных людей.",
    ["你身上散发出微弱的灵界能量，每 5 秒对附近的敌人造成较低的伤害。"] = "Вы излучаете слабую энергию Духовного мира, нанося небольшой урон ближайшим врагам каждые 5 сек..",
    ["你身上散发出灵界能量，每3秒对附近的敌人造成伤害。"] = "Вы излучаете энергию Мира Духов, нанося урон ближайшим врагам каждые 3 сек..",
    ["你还好吗？"] = "Ты в порядке?",
    ["你还是回家找妈妈吧！"] = "Тебе следует просто пойти домой и найти свою мать!",
    ["你还有一个更隐秘的名字"] = "У тебя есть другое, более секретное имя.",
    ["你还未加入俱乐部，赶快找一个心仪的俱乐部加入吧！"] = "Вы еще не вступили в клуб. Поторопитесь и найдите клуб, в который вы хотите вступить!",
    ["你还未编辑签名哦"] = "Вы еще не отредактировали свою подпись",
    ["你还没有好友哦"] = "У тебя еще нет друзей",
    ["你还没有找到真相呢……"] = "Вы еще не нашли истину...",
    ["你还没有获得权限，可联系会长授予"] = "У вас еще нет разрешения; пожалуйста, свяжитесь с президентом, чтобы предоставить его.",
    ["你还没有适应这个集体潜意识世界……"] = "Вы еще не адаптировались к этому коллективному подсознательному миру...",
    ["你还能感受到温度吗？"] = "Вы все еще чувствуете температуру?",
    ["你这个人，比我这把老骨头还爱管闲事。"] = "Ты, ты ещё более назойлив, чем мои старые кости.",
    ["你这个朋友莫非是？"] = "Неужели этот твой друг — это...?",
    ["你这是被诈骗了吧？赶快去报警吧。"] = "Похоже, вас обманули? Скорее обратитесь в полицию.",
    ["你这班我也想上"] = "Я тоже хочу учиться в твоем классе",
    ["你这瓜保真吗"] = "Настоящая ли эта дыня?",
    ["你这瓜保真吗-南瓜怪"] = "Настоящая ли ваша дыня? Тыквенный монстр",
    ["你追我赶的尸骸逃亡开始！"] = "Погоня за выживанием против мертвецов началась!",
    ["你退出了团队"] = "Вы покинули группу.",
    ["你退出了队伍"] = "Вы покинули команду.",
    ["你逃不掉的……种子！"] = "Тебе не сбежать... Семя!",
    ["你选择向%s宣战，请选择宣战场次："] = "Вы решили объявить войну %s, выберите боевую сессию:",
    ["你造成的每次伤害有50%概率召唤烈阳炮，对目标造成你的生命值上限50%的额外伤害，此效果对同一目标每2秒最多触发一次。"] = "Каждый раз, когда вы наносите урон, с вероятностью 50% вызываете Пушку Пылающего Солнца, которая наносит цели дополнительный урон, равный 50% от вашего максимального здоровья. Этот эффект может срабатывать не чаще одного раза в 2 сек. на одной и той же цели.",
    ["你邀请的人太受欢迎了，稍后再试试吧"] = "Человек, которого вы пригласили, слишком популярен; попробуйте еще раз позже.",
    ["你都不知道车厢里的气味有多糟糕。"] = "Вы даже не представляете, какой неприятный запах в вагоне.",
    ["你都卖什么？"] = "Что ты продаёшь?",
    ["你都治什么病？"] = "Какие болезни вы лечите?",
    ["你都等了好久了……"] = "Вы долго ждали...",
    ["你醉了"] = "Ты пьян",
    ["你闯出了玫瑰天堂，先别松懈，他们还在后面。"] = "Ты вырвался из Розового рая, но не расслабляйся: они все еще преследуют тебя.",
    ["你防我防大家防，金镑诈骗无处藏！！！"] = "Остерегайтесь друг друга, мошенничество с золотом повсюду!!!",
    ["你陷入无尽循环的噩梦，经历多次死亡和意志的摧残后，再次从森林中醒来，但除了胸口和太阳穴的疼痛，什么都想不起来。经过调查，你按照羊皮纸上的启示，找齐三个预言之物，却意外闯入向邪神献祭的仪式。幸好“愚者”先生及时出现，为你嫁接来自未来命运中的力量，帮助你对抗梦中残留的污染。你没有向邪神屈服，最终觉醒不灭之力，战胜“月之污染”。在“愚者”先生和塔罗会的帮助下，你身上的污染被暂时封印，即将从现实中醒来。"] = "Вы попадаете в бесконечный круг кошмаров и, пережив множественные смерти и разрушение своей воли, снова просыпаетесь в лесу, но кроме боли в груди и висках ничего не можете вспомнить. После расследования вы следуете откровениям на пергаменте и находите три пророческих предмета, но случайно вмешиваетесь в ритуал жертвоприношения злому богу. К счастью, вовремя появляется Мистер Шут, чтобы передать вам силу будущей судьбы, помогая противостоять порче, оставшейся в вашем сне. Вы не подчиняетесь злому богу, в конечном итоге пробуждая Бессмертную Силу и побеждая «Лунную Порчу». С помощью мистера Шута и Клуба Таро порча на вас временно запечатана, и вы вот-вот проснетесь в реальности.",
    ["你需要我提供什么帮助吗？"] = "Вам нужна помощь от меня?",
    ["你骂我？"] = "Ты меня ругаешь?",
    ["你！"] = "Ты!",
    ["你！你！那边的！还有你"] = "Ты! Ты! Тот, что там! И ты тоже!",
    ["你，"] = "Ты,",
    ["你，{{先生|女士}}，就是你，你觉得这公平吗？我只是想让我的未婚妻舒适一些——"] = "Вы, {{господин|госпожа}}, да, именно вы, думаете, это справедливо? Я просто хочу, чтобы моей невесте было немного удобнее—",
    ["你，你是什么人？不，不要过来！"] = "Ты, кто ты? Нет, не подходи!",
    ["佣兵小队"] = "Отряд наемников",
    ["佩内洛普"] = "Пенелопа",
    ["佩吉"] = "Пегги",
    ["佩奇"] = "Страница",
    ["佩妮"] = "Пенни",
    ["佩戴"] = "Оборудовать",
    ["佩戴中"] = "Оборудовано",
    ["佩戴数量<HighLight>%s/%s</>"] = "Надето: <HighLight>%s/%s</>",
    ["佩戴数量<HighLight>1/3</>"] = "Надето: <HighLight>1/3</>",
    ["佩戴者眼中的扭曲，贿赂秩序的真理。"] = "Искажение в глазах владельца подкупает истину порядка.",
    ["佩戴超过60秒后，灯神从沉眠中苏醒，开始按自己的理解回应佩戴者的愿望：\n<Yellow>青春永驻</>：使用解控技时，如果生命值低于<Yellow>50%</>，则灯神满足你的“愿望”，使你获得青春永驻：<Yellow>30</>秒内buffdisc(*id)\n<Yellow>同心之援</>：使用终结技时，如果<Yellow>30</>米内有至少1名队友，则灯神满足你的“愿望”，使你获得同心之援：<Yellow>30</>秒内buffdisc(*id)\n<Yellow>背水一击</>：除解控技和终结技外，技能均进入冷却时，如果<Yellow>30</>米内没有队友，则灯神满足你的“愿望”，使你获得背水一击：<Yellow>30</>秒内buffdisc(*id)\n所有愿望均会触发60秒的冷却时间，同心之援与背水一击共享冷却。"] = "После экипировки более чем на 60 секунд Джинн пробуждается ото сна и начинает исполнять желания владельца в соответствии с собственным пониманием:\n<Yellow>Вечная молодость</>: при использовании навыка снятия контроля, если запас здоровья ниже <Yellow>50%</>, Джинн исполняет ваше «желание», даруя Вечную молодость: buffdisc(*id) на <Yellow>30</> сек.\n<Yellow>Единая помощь</>: при использовании добивающего навыка, если в радиусе <Yellow>30</> м есть хотя бы 1 союзник, Джинн исполняет ваше «желание», даруя Единую помощь: buffdisc(*id) на <Yellow>30</> сек.\n<Yellow>Решающий удар</>: когда все навыки, кроме навыка снятия контроля и добивающего, находятся на перезарядке, если в радиусе <Yellow>30</> м нет союзников, Джинн исполняет ваше «желание», даруя Решающий удар: buffdisc(*id) на <Yellow>30</> сек.\nВсе желания вызывают перезарядку длительностью 60 сек., а «Единая помощь» и «Решающий удар» имеют общую перезарядку.",
    ["佩里"] = "Перри",
    ["佯装离开"] = "Притворись, что уходишь",
    ["佳木斯"] = "Цзямусы",
    ["使<HighLight>2</>格内敌人的防御降低<HighLight>30%</>。"] = "Снижает защиту врагов в радиусе <HighLight>2</> клеток на <HighLight>30%</>.",
    ["使<HighLight>2</>格内敌人的防御降低<HighLight>35%</>。"] = "Снижает защиту врагов в радиусе <HighLight>2</> клеток на <HighLight>35%</>.",
    ["使<HighLight>2</>格内的敌人每秒损失其最大生命值的<HighLight>1%</>，并使其受到的治疗效果降低<HighLight>30%</>，重伤持续<HighLight>5</>秒，处于范围内时刷新持续时间。"] = "Заставляет врагов в пределах <HighLight>2</> клеток терять <HighLight>1%</> от макс. здоровья в секунду и снижает получаемое ими исцеление на <HighLight>30%</>. Тяжёлое ранение длится <HighLight>5</> сек. и обновляется, пока цель в зоне действия.",
    ["使<HighLight>2</>格内的敌人每秒损失其最大生命值的<HighLight>2%</>，并使其受到的治疗效果降低<HighLight>30%</>，重伤持续<HighLight>5</>秒，处于范围内时刷新持续时间。"] = "Заставляет врагов в пределах <HighLight>2</> клеток терять <HighLight>2%</> от макс. здоровья в секунду и снижает получаемое ими исцеление на <HighLight>30%</>. Тяжёлое ранение длится <HighLight>5</> сек. и обновляется, пока цель в зоне действия.",
    ["使封印物负面效果失效，所有技能等级+1，伤害减免提升%s"] = "Нейтрализует негативные эффекты Запечатанного Артефакта, уровни всех навыков +1, снижение входящего урона повышается на %s",
    ["使封印物负面效果失效，所有技能等级+1，伤害加深提升%s"] = "Обнуляет отрицательные эффекты запечатанного артефакта, все уровни навыков +1, усиление урона %s",
    ["使封印物负面效果失效，所有技能等级+1，伤害加深提升5%。封印物填充的<愚者>词条为2/3条时，激活额外效果：伤害加深提高5%/10%、伤害减免提高5%/10%。"] = "Отключает негативные эффекты Запечатанного Артефакта, повышает уровень всех навыков на 1, Усиление урона повышается на 5%. Когда в Запечатанном Артефакте заполнено 2/3 записи <Дурак>, активируются дополнительные эффекты: Усиление урона повышается на 5%/10%, Снижение урона повышается на 5%/10%.",
    ["使封印物负面效果失效，所有技能等级+1，伤害加深提升5%。封印物填充的<愚者>词条为2条时，激活额外效果：伤害加深提高5%、伤害减免提高5%。"] = "Отключает негативные эффекты Запечатанного Артефакта, повышает уровень всех навыков на 1, Усиление урона повышается на 5%. Когда в Запечатанном Артефакте заполнено 2 записи <Дурак>, активируется дополнительный эффект: Усиление урона повышается на 5%, Снижение урона повышается на 5%.",
    ["使徒"] = "Апостол",
    ["使徒-头部特效（未进战可用）"] = "Апостол: спецэффект головы (доступен вне боя)",
    ["使怪物目标的仇恨对象锁定为自身。"] = "Заставляет цель монстра захватить вас.",
    ["使我们远离邪恶的沾染，摆脱厄难的缠绕……"] = "Сохрани нас от осквернения зла и освободи нас от пут бедствий...",
    ["使本技能进入CD/冷却（或扣除一次充能）"] = "Поместите этот навык на перезарядку (или вычтите один заряд).",
    ["使用"] = "Использовать",
    ["使用\"共感手铐\""] = "Используйте наручники эмпатии",
    ["使用1次游历药品"] = "Используйте 1 лекарство для путешествий.",
    ["使用1次社交表情动作"] = "Использовать социальную эмоцию 1 раз",
    ["使用2005179"] = "Используйте 2005179",
    ["使用2005180"] = "Используйте 2005180",
    ["使用2次光之折射后张开洞察之眼。"] = "Используйте Преломление Света 2 раза, чтобы открыть Око Проницательности.",
    ["使用2次光之折射后张开洞察之眼，洞察之眼命中的人脚下会生成真理之眼。"] = "После 2-кратного использования «Преломления света» откройте «Таинственные глаза»; Глаз Истины будет создан у ног тех, кого поразили Глаза Тайны.",
    ["使用3次火焰跳跃后对范围内敌人造成一次大量伤害。"] = "Использование Flame Jump 3 раза наносит огромный урон врагам в радиусе действия.",
    ["使用3次火焰跳跃后释放一次脚下伤害。"] = "Высвободите урон у своих ног после 3-кратного использования «Пламенного прыжка».",
    ["使用<Highlight>人造死神</>可以驱散附近所有玩家的<Highlight>暗光</>效果"] = "Использование <Highlight>Artificial Death</> может рассеять эффект <Highlight>Dark Light</> со всех ближайших игроков.",
    ["使用<Highlight>灰雾感知</>探测<Highlight>乌暗之影</>的位置，并寻找空隙躲避攻击"] = "Используйте <Highlight>Серый Туман Perception</>, чтобы определить местоположение <Highlight>Dark Shadow</> и найти бреши, чтобы избежать атак.",
    ["使用<Highlight>灰雾感知</>探测<Highlight>魔狼眷族</>的位置并转火攻击，<Highlight>风暴祷言</>可以击晕<Highlight>魔狼眷族</>使其暂时显形并失去攻击和移动能力"] = "Используйте <Highlight>Gray Fog Perception</>, чтобы определить местонахождение <Highlight>Demon Wolf Kin</> и переключить цели, чтобы атаковать их. <Highlight>Storm Prayer</> может оглушить <Highlight>Demon Wolf Kin</>, делая его временно видимым и лишая его способности атаковать и двигаться.",
    ["使用<Highlight>灰雾感知</>探测魔狼雕像的位置并在黑暗吞噬全场之前击碎所有魔狼雕像，<Highlight>风暴祷言</>同样可以击碎雕像，同时需要注意使用<Highlight>人造死神</>驱散乌黯魔狼施加的暗光效果"] = "Используйте <Highlight>Серый Туман Perception</>, чтобы определить местонахождение статуй Демонов-Волков и разрушить их все, прежде чем Темное Пожирание поглотит поле. <Highlight>Штормовая молитва</> также может разбивать статуи. В то же время обязательно используйте <Highlight>Artificial Death</>, чтобы рассеять эффект Темного Света, наложенный Темным Демоническим Волком.",
    ["使用<Highlight>解控或位移技能</>，离开技能中心。"] = "Используйте <Highlight>Control Break или Displacement Skill</>, чтобы покинуть центр навыка.",
    ["使用<Highlight>解控技能</>，及时拉开距离。"] = "Используйте <Highlight>навык снятия контроля</>, чтобы вовремя разорвать дистанцию.",
    ["使用<Highlight>金币飞掷</>，给予贫苦人足够的理智金币，贫苦人将恢复理智<Highlight>转化为我方阵营助战</>。"] = "Используйте <Highlight>Gold Coin Toss</>, чтобы раздать бедным достаточно рациональные золотые монеты. Бедняки вернут себе разум, и <Highlight> превратится в нашу фракцию, чтобы помочь в битве </>.",
    ["使用<Reminder_Red>光元素</>解开暗影封印"] = "Используйте световой элемент <Reminder_Red> </>, чтобы сломать теневую печать.",
