    ["我的出售"] = "Мои объявления",
    ["我的利润："] = "Моя прибыль:",
    ["我的剑放在这里，神祝福它永远锋利。"] = "Мой меч покоится здесь, и Бог благословил его быть вечно острым.",
    ["我的原则是，绝对不允许拖欠租金！"] = "Мой принцип – я категорически не допускаю задолженности по квартплате!",
    ["我的哥哥"] = "Мой старший брат",
    ["我的商队"] = "Мой Караван",
    ["我的嗓音是个人特色！"] = "Мой голос – моя личная торговая марка!",
    ["我的团队"] = "Моя группа",
    ["我的塔罗占卜很准的。"] = "Мои гадания на Таро очень точны.",
    ["我的复活技能冷却时间还有%s秒"] = "Перезарядка моего навыка воскрешения: еще %s сек.",
    ["我的大儿子卖雨伞，小儿子卖遮阳帽。一个盼雨天，一个盼晴天——可这天气哪能两头都顾上啊？！"] = "Мой старший сын продаёт зонты, а младший — шляпы от солнца. Один ждёт дождя, другой — солнца... но разве погода может угодить обоим?!",
    ["我的头好痛。"] = "У меня так болит голова.",
    ["我的奖励"] = "Мои награды",
    ["我的女神啊，你的读者快把出版社的门槛踏破了……"] = "Моя Богиня, твои читатели вот-вот переступят порог издательства...",
    ["我的女神！阿比倒下了！阿比倒下了！出现了新的冠军！让我们欢呼！"] = "Моя Богиня! Эбби упала! Эбби упала! Появился новый чемпион! Давайте подбадриваем!",
    ["我的好友"] = "Мои друзья",
    ["我的妹妹"] = "Моя маленькая сестра",
    ["我的妻子总是抱怨城堡里太阴暗，她喜欢阳光，喜欢温暖的感觉…… "] = "Моя жена всегда жаловалась, что замок слишком мрачный; ей нравился солнечный свет, нравилось ощущение тепла...",
    ["我的姐姐，你还是一向如此挑剔。这样好了，等表演结束，我们去找点家乡风味的特色餐馆。"] = "Сестрёнка, ты как всегда такая привередливая. Хорошо, после представления пойдём поищем ресторан с блюдами родного края.",
    ["我的学生很好，贝克兰德的一切都很好。"] = "У моих учеников все в порядке, и в Баклунде все в порядке.",
    ["我的孩子，你怎么没继承爸爸的审美？旁边的好一万倍！"] = "Дитя моё, почему ты не унаследовал папин вкус? Та, что рядом, в десять тысяч раз лучше!",
